// Hand-written entries are single sources of truth for the playlist, sticky
// transport, turntable spin-up, and spectrum analyzer audition. The
// `featuredArtists.gen.ts` file below is AUTO-GENERATED by
// `scripts/generate-featured-artists.ts` from the on-disk files in
// `public/audio/featured-artists/` + `public/images/Thumbnails/` — do not
// edit it by hand. See `docs/featured-artists-ingestion.md`.
//
// Hand-written overrides: `featuredArtistsOverrides` below take precedence
// over generated entries by audioUrl, so curated metadata survives across re-scans.

import { FeaturedTrack } from "./featuredTrackTypes";
import { featuredArtists as generatedFeaturedArtists } from "./generated/featuredArtists.gen";
import { featuredArtistsOverrides } from "./featuredArtists.overrides";

// ── Featured artists (public/audio/featured-artists/) ────────────────────────
// Hand-written overrides for metadata that cannot be derived from filenames
// (display name, artist, gear tag, hardware). The generated array provides
// entries for every audio file on disk; entries here take precedence so
// curated metadata survives across re-scan.
// Build final per-track metadata by merging generated over overrides.
// If an override has the same audioUrl as a generated entry, the override wins.
function normalizeAudioUrl(url: string): string {
  return decodeURIComponent(url || "").replace(/\s+/g, " ").trim().toLowerCase();
}
function buildFeaturedArtists(): FeaturedTrack[] {
  // Index generated by audioUrl
  const genMap = new Map(generatedFeaturedArtists.map((t) => [normalizeAudioUrl(t.audioUrl), t]));
  // Apply overrides (they win on matching audioUrl)
  const result: FeaturedTrack[] = [];
  for (const t of generatedFeaturedArtists) {
    const override = featuredArtistsOverrides.find(
      (o) => normalizeAudioUrl(o.audioUrl) === normalizeAudioUrl(t.audioUrl),
    );
    result.push(override ?? t);
  }
  // Append any overrides whose audioUrl was not in the generated set
  // (extremely unlikely but handle it)
  for (const o of featuredArtistsOverrides) {
    if (!result.some((t) => normalizeAudioUrl(t.audioUrl) === normalizeAudioUrl(o.audioUrl))) {
      result.push(o);
    }
  }
  return result;
}

export const featuredArtists = buildFeaturedArtists();

